const paintTex = (col, stripe) => once('pt24' + col + stripe, () => ctex(256, 256, (c, w, h) => { c.fillStyle = hex(col); c.fillRect(0, 0, w, h); if (stripe) { c.fillStyle = hex(stripe); for (let x = 0; x < w; x += 64) c.fillRect(x, 0, 26, h); } noiseFill(c, w, h, 0.05, 2600); }));
