// window-pane cookie for a sunbeam spot light
const paneTex = () => once('pane24', () => ctex(256, 256, (c, w, h) => { c.fillStyle = '#000'; c.fillRect(0, 0, w, h); c.fillStyle = '#fff'; for (const [x, y] of [[44, 44], [134, 44], [44, 134], [134, 134]]) c.fillRect(x, y, 78, 78); }));
export function sunSpot(S, pos, target, { col = 0xffd9a0, intensity = 260, angle = 0.34, dist = 60 } = {}) { const s = new THREE.SpotLight(col, intensity, dist, angle, 0.25, 1.2); s.position.set(...pos); s.target.position.set(...target); s.map = paneTex(); s.castShadow = true; s.shadow.mapSize.set(1024, 1024); s.shadow.bias = -0.001; S.add(s, s.target); return s; }
