  const body = new THREE.Group(); g.add(body); put(body, mesh(rb(1.25, 1.02, 1.95, 0.3), fur), [0, 0.5, 0.95]); put(body, mesh(rb(0.8, 0.5, 1.2, 0.2), wh), [0, 0.2, 1.1]); put(body, mesh(rb(0.86, 0.7, 0.3, 0.14), wh), [0, 0.5, 1.84]);
  const legs = {}; for (const [k, x] of [['fr', -0.38], ['fl', 0.38], ['rr', -0.44], ['rl', 0.44]]) { const p = new THREE.Group(); g.add(p); put(p, mesh(rb(0.38, 0.62, 0.4, 0.12), furF), [0, -0.3, 0]); put(p, mesh(rb(0.42, 0.24, 0.5, 0.1), wh), [0, -0.54, 0.05]); p.userData.x = x; legs[k] = p; }
  const tail = []; let par = g; for (let i = 0; i < 5; i++) { const p = new THREE.Group(); par.add(p); put(p, mesh(rb(0.26 - i * 0.012, 0.5, 0.26 - i * 0.012, 0.1), i === 4 ? wh : furF), [0, 0.22, 0]); if (i) p.position.y = 0.42; tail.push(p); par = p; }
  const headG = new THREE.Group(); g.add(headG); headG.scale.setScalar(0.94);
  const A = makeAvatar({ skin: col, name, face, hair: null, shirt: col, pants: col, blob: false }); const keep = new Set(); A.headMesh.traverse(o => keep.add(o)); A.root.traverse(o => { if (o.isMesh && !keep.has(o)) o.visible = false; }); if (A.blob) A.blob.visible = false;
