  const mk = (col) => { const a = []; for (let i = 0; i < n; i++) { const m = new THREE.Sprite(new THREE.SpriteMaterial({ map: st, color: col, transparent: true, depthWrite: false, depthTest: false, blending: THREE.AdditiveBlending })); m.visible = false; m.renderOrder = 50; S.add(m); a.push(m); } return a; };
  const A = mk(0xffe27a), B = mk(0x8ae8ff), L = [0, 1].map(() => { const l = new THREE.PointLight(0xfff0c0, 0, 14, 1.6); S.add(l); return l; }); const P = [new THREE.Vector3(), new THREE.Vector3()];
